        #region InsertExChangeRate

        public string InsertExChangeRate(string actualrate, string currency, string minbet, string minbetlive, string Code, string Description, string MultipliedBy, string offerSite)
        {
            string msg = "";
            try
            {
                Hashtable hash = new Hashtable();
                hash.Add("userid", AppSession.AccId);
                hash.Add("actualrate", actualrate);
                hash.Add("currency", currency.Trim());
                hash.Add("minbet", minbet);
                hash.Add("minbetlive", minbetlive);
                hash.Add("offersite", offerSite);

                hash.Add("ip", HttpContext.Current.Request.UserHostAddress);
                hash.Add("errcode", 0);
                hash.Add("errmsg", "");
                hash.Add("exchangeid", 0);

                hash.Add("code", Code.Trim());
                hash.Add("description", Description);
                hash.Add("multipliedby", Convert.ToInt32(MultipliedBy.Trim()));
                int exchangeid = 0;
                var result = IBCProvider.ExChangeRate.ExchangeIns(hash, ref exchangeid);
                msg = result.ErrorMessage;
                if (result.ErrorCode == 0)
                {
                    var response = casinoApiService.UpdateExchange(new CasinoApiRequest
                    {
                        Call = new List<CasinoApiCurrencyParam> {
                            new CasinoApiCurrencyParam
                            {
                                ActualRate = CastAide.AsDouble(actualrate),
                                Currency = currency.Trim(),
                                IBCExchangeId = exchangeid,
                                ISOCode = Code
                            }
                        }
                    });
                    if (!response.IsSuccess)
                    {
                        msg = response.Result[0].ErrorCode + ": " + response.Result[0].Description;
                    }
                }
            }
            catch (Exception ex)
            {
                msg = ex.Message;
                LogExtensions.ExceptionHandler(ex);
            }

            return msg;
        }

